contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    // params: sender and recipient will be addresses represented as uint160 values,
    // amount is token amount to transfer, and allowedFlag decides whether to mark
    // sender or recipient as allowed via changeOwner and set role indirectly by
    // using transfer from owner-created allowances. Because _allowedRoles is private
    // we cannot set it directly; instead we will call functions that are public: transfer/transferFrom/approve.
    // We only assert that when a non-reverting transfer (either transfer or transferFrom)
    // completes, totalSupply and address(c).balance are unchanged.
    function run(address from, address to, uint256 amount, bool useTransferFrom, uint256 approveAmount) public payable {
        require(from != address(0) && to != address(0), true);

        // record observables before the action
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = address(c).balance;

        bool reverted = false;

        if (!useTransferFrom) {
            // try calling c.transfer(to, amount) from this contract as msg.sender
            // but run must call top-level state-changing calls directly; do it and catch revert
            try c.transfer(to, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // use approve + transferFrom path: first approve this contract to spend from 'from'
            // We cannot make c.approve be from another address than this contract. So emulate by
            // approving and then calling transferFrom; this attempts transferFrom(from, to, amount) as this contract
            try c.approve(to, approveAmount) {
                // approval succeeded (from this contract), now attempt transferFrom using provided 'from'
            } catch {
                // ignore
            }

            try c.transferFrom(from, to, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Observables after
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = address(c).balance;

        // General rule: if the attempted transfer did NOT revert then totalSupply and contract Ether balance are unchanged
        assert(reverted || (afterTotal == beforeTotal && afterBalance == beforeBalance));
    }

    receive() external payable {}
}

