        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = address(c).balance;

        bool reverted = false;

        if (!useTransferFrom) {
            // attempt transfer(to, amount) as this contract
            try c.transfer(to, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // attempt transferFrom(from=this contract, to, amount) as this contract
            try c.transferFrom(address(this), to, amount) {
                reverted = false;
            } catch {
