contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0));
        // ensure this contract has enough token balance to attempt transfer: nothing else can mint here
        // read before-values
        uint256 totalBefore = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(address(this));
        uint256 balRecipientBefore = c.balanceOf(recipient);

        // approve c to spend on behalf of this contract and then attempt a transferFrom if needed;
        // but contract c implements transfer which transfers msg.sender's tokens — here msg.sender will be this test contract.
        // First, ensure allowance path: call approve so transferFrom could be used by others; not necessary for transfer()
        // Try performing a transfer from this contract to recipient and capture revert.
        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 totalAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(address(this));
        uint256 balRecipientAfter = c.balanceOf(recipient);

        // Property: if transfer did NOT revert, the totalSupply is unchanged and the sum of sender+recipient balances after equals sum before
        // If transfer reverted, no state change is required by this property (we allow revert). The assert encodes the general rule for successful transfers.
        assert(reverted || (totalAfter == totalBefore && balSenderAfter + balRecipientAfter == balSenderBefore + balRecipientBefore));
    }

    receive() external payable {}
}

