contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters: senderIsAllowed to choose whether msg.sender (this test contract)
    // is granted allowed role before transfer; recipient and amount determine transfer.
    // We also allow funding the c contract from this test contract to ensure it has balance
    // to pay rewards when needed.
    function run(bool senderIsAllowed, address recipient, uint256 tAmount, uint256 fundAmount) public payable {
        require(recipient != address(0), "recipient nonzero");
        // fund this contract if needed then forward funds to c so c can have balance
        if (fundAmount > 0) {
            require(address(this).balance >= fundAmount, "insufficient ether to fund");
            (bool s,) = address(c).call{value: fundAmount}("");
            // ignore success; funding optional
            s; 
        }

        // Ensure we can call methods on c that are public: use only public interface.
        // Before values: read txReward for recipient.
        uint256 beforeReward = c.txReward(recipient);

        // Also read current parameters affecting reward calculation.
        uint256 minTxn = c.minTxnAmount();
        uint256 percent = c.percent();
        uint256 rewardRate = c.rewardRate();

        // We need to set allowed role of msg.sender or recipient. The contract C has no public setter
        // for _allowedRoles; but constructor made deployer owner and our InvMutTest was deployed by
        // test harness, not owner, so we cannot change roles. However we can rely on calling transfer
        // from an allowed role by using the contract's public functions: transfer is called by msg.sender
        // of the transfer call. The InvMutTest contract will call c.transfer(recipient, tAmount) so
        // msg.sender inside c is address(this). We cannot mutate _allowedRoles, so the only way to make
        // the transfer take the buy/sell branches is if c's internal _allowedRoles[address(this)] is true
        // by default in the deployed C; since we cannot assume that, we will instead exercise the general
        // property about txReward: reward can only increase (never decrease) and increases equal computed reward
        // when reward transfer happens. We'll perform a transfer and observe whether txReward increases by
        // either zero or the computed rewardAmount; it must not increase by any other amount.

        // Perform transfer from this contract's address to recipient. First, ensure this contract has
        // enough token balance by reading c.balanceOf(address(this)) and only proceed if >= tAmount.
        uint256 myBal = c.balanceOf(address(this));
        // If tAmount is zero the transfer would revert in C; require non-zero to reach logic.
        require(tAmount > 0, "tAmount>0");

        // If balance insufficient, try to approve and transferFrom path won't help because allowances are zero.
        // So require myBal >= tAmount to ensure transfer will not revert due to insufficient balance.
        require(myBal >= tAmount, "insufficient token balance for transfer");

        bool reverted = false;
        try c.transfer(recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterReward = c.txReward(recipient);

        // Compute the nominal reward amount for this tAmount according to contract parameters.
        // Avoid division by zero: percent is public and set to 10000 in constructor; still guard.
        uint256 expectedReward = 0;
        if (percent != 0) {
            expectedReward = (tAmount * rewardRate) / percent;
        }

        // The asserted general rule:
        // If the transfer reverted, then txReward must be unchanged.
        // If transfer succeeded, then txReward[recipient] either stayed the same or increased exactly by expectedReward.
        assert(
            (reverted && afterReward == beforeReward)
            || (!reverted && (afterReward == beforeReward || afterReward == beforeReward + expectedReward))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters:
    // recipient - target of the transfer
    // tAmount - token amount to transfer (must be >0)
    // fundAmount - optional ETH forwarded to c so it can have balance for reward payments
    function run(address recipient, uint256 tAmount, uint256 fundAmount) public payable {
        require(recipient != address(0), "recipient nonzero");
        require(tAmount > 0, "tAmount>0");

        // Optionally fund contract c with ETH so that address(c).balance may be increased.
        if (fundAmount > 0) {
            require(address(this).balance >= fundAmount, "insufficient ether to fund");
            (bool ok,) = address(c).call{value: fundAmount}("");
            // ignore ok; funding best-effort
            ok; 
        }

        // Observe relevant before-state via public getters
        uint256 beforeTxReward = c.txReward(recipient);
        uint256 myBal = c.balanceOf(address(this));
        uint256 minTxn = c.minTxnAmount();
        uint256 pct = c.percent();
        uint256 rRate = c.rewardRate();
        uint256 cBal = c.balanceOf(address(c));

        // Precondition: ensure this contract has token balance to perform transfer
        require(myBal >= tAmount, "insufficient token balance for transfer");

        // Perform the transfer as a single top-level call and capture revert status
        bool reverted;
        try c.transfer(recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        uint256 afterTxReward = c.txReward(recipient);
        uint256 afterCbal = c.balanceOf(address(c));

        // Compute the nominal reward amount (guard against zero percent);
        // percent is expected nonzero but we guard to avoid division-by-zero in assertion expression building.
        uint256 expectedReward = 0;
        if (pct != 0) {
            expectedReward = (tAmount * rRate) / pct;
        }

        // General rule to assert:
        // - If the transfer reverted, txReward for recipient is unchanged.
        // - If the transfer succeeded, txReward for recipient is >= before and cannot increase by more than expectedReward.
        //   (i.e., after - before <= expectedReward)
        // This captures that rewards never decrease and only the contract-calculated reward amount can be added.
        assert(
            (reverted && afterTxReward == beforeTxReward)
            || (
                !reverted
                && afterTxReward >= beforeTxReward
                && (afterTxReward - beforeTxReward) <= expectedReward
            )
        );
    }

    receive() external payable {}
}

