contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    // params: recipient address, amount to transfer, boolean to mark recipient as allowed role via owner change
    function run(address recipient, uint256 tAmount, bool makeRecipientAllowed) public payable {
        require(recipient != address(0), "recipient zero");

        // record observables before any state-changing operations
        uint256 totalBefore = c.totalSupply();
        address pairBefore = c.uniswapV2Pair();
        uint256 balThisBefore = c.balanceOf(address(this));
        uint256 balRecipientBefore = c.balanceOf(recipient);
        uint256 balContractBefore = c.balanceOf(address(c));

        // ensure this contract has enough tokens to attempt transfers: approve/mint not available externally,
        // but constructor of C minted all tokens to deployer (which deployed c). Here msg.sender is InvMutTest contract
        // that deployed c, so it should hold tokens; if not enough balance the transfer will revert and we capture that.

        // Optionally set allowed role by calling changeOwner then using onlyOwner to set roles is not exposed.
        // Instead, we rely on the fact that constructor set _owner to deployer; since InvMutTest deployed c, it is owner.
        // MakeRecipientAllowed: if true, call c.changeUniswapV2Pair to mutate a public variable (onlyOwner) to exercise owner privilege.
        if (makeRecipientAllowed) {
            // changeUniswapV2Pair is onlyOwner; as owner we can call it — use recipient as arbitrary address to change state
            c.changeUniswapV2Pair(recipient);
        }

        bool reverted = false;
        // make the transfer and catch revert
        try c.transfer(recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-state
        uint256 totalAfter = c.totalSupply();
        address pairAfter = c.uniswapV2Pair();
        uint256 balThisAfter = c.balanceOf(address(this));
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 balContractAfter = c.balanceOf(address(c));

        // General rule expressed as single assert:
        // - totalSupply and uniswapV2Pair never change because transfer should not affect total supply and onlyOwner changeUniswapV2Pair was explicit above
        // - If the transfer reverted then balances must be unchanged; otherwise sum of observed balances (this + recipient + contract) after equals before
        //   unless a reward transfer from contract to recipient or sender occurred; but reward transfers move tokens from contract to the counterparty,
        //   so the combined sum of these three addresses remains the same (tokens only move between them).
