contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property-based check
    // params: recipient, amount, approveFlag and allowanceSpender to cover transferFrom path
    function run(address recipient, uint256 amount, bool useTransferFrom, address allowanceSpender) public payable {
        require(recipient != address(0), "recipient nonzero");
        // Observe initial total supply and balances of relevant accounts
        uint256 totalBefore = c.totalSupply();
        address self = address(this);
        uint256 balSenderBefore = c.balanceOf(self);
        uint256 balRecipientBefore = c.balanceOf(recipient);
        uint256 balContractBefore = c.balanceOf(address(c));

        // If needed for transferFrom, set allowance (call approve)
        if (useTransferFrom) {
            // approve spender (allowanceSpender) to spend from this test contract
            // We call c.approve as a top-level state-changing call
            // amount can be zero; approve is still a valid state change
            c.approve(allowanceSpender, amount);

            // Now attempt to have allowanceSpender perform transferFrom from this test contract
            // But we cannot make allowanceSpender call c.transferFrom because msg.sender for that call would be this contract.
            // Instead, we check the invariant by directly calling transferFrom as this contract (allowed when spender == this)
            // So require allowanceSpender equals this contract when intending transferFrom
            // If not equal, we still call transfer (fallback to transfer)
        }

        bool didRevert = false;
        // perform either transfer or transferFrom depending on flag and allowanceSpender
        if (useTransferFrom && allowanceSpender == address(this)) {
            // call transferFrom from this contract: sender = this, recipient = recipient
            try c.transferFrom(address(this), recipient, amount) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        } else {
            // call simple transfer
            try c.transfer(recipient, amount) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        }

        // Observe after-values
        uint256 totalAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(self);
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 balContractAfter = c.balanceOf(address(c));

        // General rule: transfers must not change totalSupply, and sum of observed balances of (sender + recipient + contract) changes consistently
        // Specifically: totalSupply unchanged, and (balSenderBefore + balRecipientBefore + balContractBefore) == (balSenderAfter + balRecipientAfter + balContractAfter)
        // Use assert as single final check
        assert(totalBefore == totalAfter && (balSenderBefore + balRecipientBefore + balContractBefore) == (balSenderAfter + balRecipientAfter + balContractAfter));
    }

    receive() external payable {}
}

