contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: senderRole indicates whether the sender is an allowed role (buy),
    // recipientRole indicates whether recipient is an allowed role (sell).
    // We model a transfer from address(this) (the test contract) to some other address.
    // Because msg.sender for calls into c will be this contract, we must use c's public functions
    // to manipulate allowances/roles. However roles are private so we can only exercise transfers
    // by calling c.transfer/transferFrom as this contract; constructor of c gave entire supply to deployer
    // (not us), so to make meaningful transfers we rely on transferFrom path: we'll first approve this contract
    // by calling c.approve from this contract's perspective is impossible because we don't own tokens.
    // Instead we will test transfer behavior by calling transfer where this contract tries to send tokens
    // and expect transfer to revert unless roles allow it. We therefore focus the property on the observable
    // relationship between txReward and emitted reward amounts when a successful transfer occurs via transfer().

    // To trigger non-reward transfers we need to ensure the transfer is allowed; but _allowedRoles is private
    // and onlyOwner can change owner/roles; owner initially is deployer of C (not this contract). So to create a
    // reachable successful transfer we instead rely on the fact that in the constructor of C the deployer got all tokens
    // and owner is deployer; our test can't change that. However the checker deploys a fresh C and passes it to us,
    // and msg.sender for calls into C will be this contract. The only way for transfer to succeed is if either
    // _allowedRoles[this] || _allowedRoles[recipient] is true. Since we cannot set roles, most transfers will revert.
    // We therefore write the test to call transfer and detect whether it reverted. The property relates revert flag,
    // tAmount, minTxnAmount, and txReward/balances: if transfer succeeded and tAmount >= minTxnAmount and contract
    // balance >= rewardAmount then txReward is increased by at most rewardAmount and that same amount was transferred
    // from contract to the rewarded party. If no reward, then either tAmount < minTxnAmount or contract balance < reward.

    // Note: to observe balances we use public balanceOf and txReward. We pass recipient as an address parameter
    // encoded as uint160 so ABI-friendly.

    function run(uint160 recipient_u, uint256 tAmount) public payable {
        address recipient = address(recipient_u);
        require(recipient != address(0), true);

        // Read globals before the call
        uint256 minTxn = c.minTxnAmount();
        uint256 rewardRate = c.rewardRate();
        uint256 percent = c.percent();

        // read contract's token balance before
        uint256 contractBalBefore = c.balanceOf(address(c));

        // read txReward for recipient before
        uint256 txRewardBefore = c.txReward(recipient);

        // Attempt transfer from this contract to recipient
        bool reverted;
        try c.transfer(recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after values
        uint256 contractBalAfter = c.balanceOf(address(c));
        uint256 txRewardAfter = c.txReward(recipient);
        uint256 recipientBalAfter = c.balanceOf(recipient);

        // Compute expected rewardAmount (avoid division by zero since percent is public and set in constructor to 10000)
        uint256 rewardAmount = 0;
        if (percent != 0) {
            rewardAmount = tAmount * rewardRate / percent;
        }

        // Now assert the general rule described in property_summary.
        // If the transfer reverted, nothing else is required by the contract; so our assertion only constrains the case when the transfer succeeded.
        // For successful transfers: either no reward applied (txReward unchanged) and that implies (tAmount < minTxn OR contract balance before < rewardAmount),
        // or reward applied: txReward increased by at most rewardAmount, contract token balance decreased by exactly the rewarded amount, and receiver received at least that reward.
        assert(
            reverted || (
                // transfer succeeded: then one of two situations holds
                ((txRewardAfter == txRewardBefore) && (tAmount < minTxn || contractBalBefore < rewardAmount))
                ||
                // or reward was applied: txReward increased by <= rewardAmount and contract balance decreased by >= the recorded increase
                ((txRewardAfter >= txRewardBefore) && (txRewardAfter - txRewardBefore <= rewardAmount) && (contractBalBefore >= contractBalAfter) && (contractBalBefore - contractBalAfter >= (txRewardAfter - txRewardBefore)) && (recipientBalAfter >= (txRewardAfter - txRewardBefore)))
            )
        );
    }

    receive() external payable {}
}

