        // Read contract's token balance and txReward for recipient before
        uint256 contractBalBefore = c.balanceOf(address(c));
        uint256 txRewardBefore = c.txReward(recipient);
        uint256 recipientBalBefore = c.balanceOf(recipient);

        // Perform the transfer and capture whether it reverted
        bool reverted;
        try c.transfer(recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values (only via public getters)
        uint256 contractBalAfter = c.balanceOf(address(c));
        uint256 txRewardAfter = c.txReward(recipient);
        uint256 recipientBalAfter = c.balanceOf(recipient);

        // Compute the nominal rewardAmount safely (guard percent != 0)
        uint256 rewardAmount = 0;
        if (percent != 0) {
            rewardAmount = (tAmount * rewardRate) / percent;
        }

        // Assert the general rule.
        // If reverted, we place no further requirement. If not reverted, then either no reward was recorded
        // (txReward unchanged) which must imply that tAmount < minTxn or contract lacked tokens for reward,
        // or a reward was recorded: the recorded increase is <= computed rewardAmount, contract's balance
        // decreased by at least that increase, and recipient's balance increased by at least that increase.
        assert(
            reverted || (
                (
                    // Case: no reward recorded
                    txRewardAfter == txRewardBefore
                    && (tAmount < minTxn || contractBalBefore < rewardAmount)
                )
                ||
                (
                    // Case: reward recorded
                    txRewardAfter >= txRewardBefore
                    && (txRewardAfter - txRewardBefore) <= rewardAmount
                    && contractBalBefore >= contractBalAfter
                    && (contractBalBefore - contractBalAfter) >= (txRewardAfter - txRewardBefore)
                    && recipientBalAfter >= recipientBalBefore
                    && (recipientBalAfter - recipientBalBefore) >= (txRewardAfter - txRewardBefore)
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
