    // single public test function taking arbitrary sender/recipient (addresses encoded as uint160), and amount
    function run(uint160 senderRaw, uint160 recipientRaw, uint256 amount) public payable {
        // derive addresses from inputs; avoid zero addresses to satisfy contract requirements
        address sender = address(senderRaw == 0 ? 1 : senderRaw);
        address recipient = address(recipientRaw == 0 ? 2 : recipientRaw);

        // Precondition: choose amount > 0 to avoid immediate revert from tAmount==0
        require(amount > 0, "amount must be > 0");

        // The freshly deployed c has total supply assigned to deployer (msg.sender of its constructor).
        // Our InvMutTest is NOT the deployer of c per problem statement, but we must operate through c's public surface.
        // To make a transfer between sender and recipient, we need sender to have sufficient balance and both
        // addresses to NOT be in _allowedRoles. _allowedRoles is private, so we cannot set it; however the constructor
        // minted full supply to c's deployer and left other addresses with zero. We can only interact with c via its
        // public functions. The safest approach is to attempt transferFrom where sender == msg.sender (this contract)
        // after approving; but this contract likely has zero balance. Instead, we will assert a property that whenever
        // a plain transfer between two externally provided accounts happens without allowed-roles path, then balances
        // change by exactly amount. We simulate that by using c.transfer with recipient and amount from this contract
        // (msg.sender for c calls will be this InvMutTest contract). To ensure the plain-transfer branch (no rewards)
        // we must call transfer between two addresses that are not allowed roles. Since we cannot set roles, we use
        // the general transfer function where sender is address(this). The check in C requires _allowedRoles[sender] || _allowedRoles[recipient]
        // so to pass that require we need at least one allowed role true. But _allowedRoles is private and by default false
        // for everyone, so plain transfer would revert. To make a meaningful, provable property that does not rely on
        // unknown private roles, instead we observe the behavior of transfer when roles are not set: it must revert with
        // "Unauthorized role". We thus assert that for any recipient and amount>0, calling c.transfer reverts with that
        // condition OR, if it succeeds, balances change exactly by amount in both accounts (no reward applied). This expresses
        // the intended invariant about non-reward transfer conserving tokens between sender and recipient when taken the simple branch.

        // Record pre-balances for this contract (sender will be address(this)) and recipient
        uint256 beforeSender = c.balanceOf(address(this));
        uint256 beforeRecipient = c.balanceOf(recipient);

        bool reverted;
        // perform the call under try/catch to detect revert
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterSender = c.balanceOf(address(this));
        uint256 afterRecipient = c.balanceOf(recipient);

        // If the call did not revert then either the allowed-role branch executed or the plain transfer branch executed.
        // We check the plain-transfer branch effect: balances should move exactly by amount (sender loses amount, recipient gains amount).
        // If the transfer used the reward branches, those also emit token moves but would additionally adjust txReward and contract balance,
        // which we cannot read precisely here; therefore the assertion requires that if transfer succeeded and neither sender nor recipient gained
        // unexpected extra tokens beyond amount, then the exact conservation holds. Concretely: if not reverted, then
        // beforeSender - afterSender == amount AND afterRecipient - beforeRecipient == amount.
        // Alternatively if the call reverted, we accept that as allowed behaviour.

        assert(
            reverted || (
                // ensure no under/overflow by doing comparisons that don't underflow
                beforeSender >= afterSender && afterRecipient >= beforeRecipient &&
                (beforeSender - afterSender) == amount && (afterRecipient - beforeRecipient) == amount
            )
        );
    }

    receive() external payable {}
}

