        require(sender != address(0) && recipient != address(0) && sender != recipient);

        // Ensure amount is strictly less than minTxnAmount to avoid reward path
        uint256 min = c.minTxnAmount();
        require(min > 0);
        if (amount >= min) {
            // reduce amount to be strictly less than minTxnAmount
            amount = min - 1;
        }
        // The contract's allowed roles mapping is private; we can only observe behavior via public interface.
        // To get the transfer to follow the "allowed sender" branch, we need sender to be an allowed role.
        // The only way to cause _allowedRoles[sender] to be true is not available via public API.
        // However the contract's constructor gave msg.sender (the deployer) a full reflected balance and set _owner.
        // Our InvMutTest was the deployer of c as specified by the problem statement, so this contract (address(this))
        // holds the initial reflected balance. We will act as that address by invoking c.transfer from this contract.
        // That means 'sender' for c.transfer will be address(this). So require sender==address(this).
        require(sender == address(this));

        // Read balances and total supply before
        uint256 beforeTotal = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(sender);
        uint256 balRecipientBefore = c.balanceOf(recipient);

        // Make sure sender has enough balance to transfer amount
        require(balSenderBefore >= amount && amount > 0);

        bool reverted = false;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balSenderAfter = c.balanceOf(sender);
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 afterTotal = c.totalSupply();

        // If call did not revert, then balances must reflect exact transfer of amount and totalSupply unchanged
        assert(reverted || (balSenderBefore - balSenderAfter == amount && balRecipientAfter - balRecipientBefore == amount && beforeTotal == afterTotal));
    }

    receive() external payable {}
}

