    // single public entry performing the property test
    // params: sender (from whose balance tokens are sent), recipient, spender (msg.sender at C will be this contract), amount, initialAllowance
    function run(address sender, address recipient, uint256 amount, uint256 initialAllowance) public payable {
        require(sender != address(0) && recipient != address(0), true);

        // The InvMutTest contract is the deployer of c, so it is c.owner() initially. We must approve the spender (which for transferFrom is msg.sender at C).
        // Here this contract will act as the spender when calling c.transferFrom. To set allowance we need the owner (sender) to call c.approve(sender=?). But we cannot make arbitrary other addresses call c.approve.
        // However, c.approve acts on msg.sender, so to arrange an allowance from 'sender' -> this contract, we require that sender == address(this).
        // Enforce sender == address(this) to allow setting allowance. This is a necessary precondition for the test to be executable using only public API.
        require(sender == address(this), true);

        // Set initial allowance from sender (this contract) to this contract's address as spender by calling approve from sender (this contract)
        bool ok = c.approve(address(this), initialAllowance);
        // approve should succeed per ERC20 semantics, check it didn't revert
        require(ok, true);

        // Read allowance before transferFrom
        uint256 allowanceBefore = c.allowance(address(this), address(this));

        // Also read balances to ensure transferFrom will have tokens: we will rely on mint at construction gave deployer tokens; since this contract deployed c, it should hold tokens.
        uint256 balBeforeSender = c.balanceOf(address(this));
        uint256 balBeforeRecipient = c.balanceOf(recipient);

        // Attempt transferFrom; capture revert status
        bool reverted = false;
        try c.transferFrom(address(this), recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state values
        uint256 allowanceAfter = c.allowance(address(this), address(this));
        uint256 balAfterSender = c.balanceOf(address(this));
        uint256 balAfterRecipient = c.balanceOf(recipient);

        // General rule: if initialAllowance < amount, transferFrom must revert and no state changes to balances or allowance occur;
        // otherwise transferFrom succeeds and decreases allowance by exactly amount and moves tokens from sender to recipient by amount.
        // Note: to avoid underflow inside assert, use comparisons.
        if (initialAllowance < amount) {
            // must have reverted and state unchanged
            assert(reverted == true
                && allowanceAfter == allowanceBefore
                && balAfterSender == balBeforeSender
                && balAfterRecipient == balBeforeRecipient);
        } else {
            // must have succeeded and allowance decreased by amount, balances updated accordingly
            assert(reverted == false
                && allowanceAfter + amount == allowanceBefore
                && balBeforeSender >= amount
                && balAfterSender + amount == balBeforeSender
                && balAfterRecipient == balBeforeRecipient + amount);
        }
    }

    receive() external payable { }
}

