contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0));
        // observe before-values via public getters
        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeSenderBal = c.balanceOf(address(this));
        uint256 beforeRecipientBal = c.balanceOf(recipient);
        uint256 beforeContractTokenBal = c.balanceOf(address(c));
        uint256 beforeContractEth = address(c).balance;
        uint256 beforeThisEth = address(this).balance;

        // make sure this contract has some tokens to send: try approving and using transfer
        // The deployed C mints total supply to deployer (constructor caller). In the checker
        // the InvMutTest deploys c, so address(this) should hold tokens; if not, transfer will revert.

        bool didRevert = false;
        try c.transfer(recipient, amount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // observe after-values
        uint256 afterSenderBal = c.balanceOf(address(this));
        uint256 afterRecipientBal = c.balanceOf(recipient);
        uint256 afterContractTokenBal = c.balanceOf(address(c));
        uint256 afterTotalSupply = c.totalSupply();
        uint256 afterContractEth = address(c).balance;
        uint256 afterThisEth = address(this).balance;

        // Assert a general conservation property when transfer did not revert:
        // - totalSupply unchanged
        // - token balances sum (sender + recipient + contract) is non-increasing and specifically unchanged
        // - contract's ETH balance unchanged and this contract's ETH balance unchanged by ERC20 transfer
        assert(
            // if it reverted, we only assert that nothing changed among observed values
            (didRevert &&
                beforeTotalSupply == afterTotalSupply &&
                beforeSenderBal == afterSenderBal &&
                beforeRecipientBal == afterRecipientBal &&
                beforeContractTokenBal == afterContractTokenBal &&
                beforeContractEth == afterContractEth &&
                beforeThisEth == afterThisEth
            ) ||
            // else (transfer succeeded): total supply preserved and token sum preserved and no ETH moved
            (!didRevert &&
                beforeTotalSupply == afterTotalSupply &&
                // sum of observed token balances preserved
                (beforeSenderBal + beforeRecipientBal + beforeContractTokenBal) == (afterSenderBal + afterRecipientBal + afterContractTokenBal) &&
                // ETH balances unchanged
                beforeContractEth == afterContractEth &&
                beforeThisEth == afterThisEth
            )
        );
    }

    receive() external payable {}
}

